"post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$exam['id']?>"><input type="hidden" name="status" value="closed"><button class="btn btn-sm btn-danger">بستن</button></form><?php elseif($exam['status']==='closed'):?><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$exam['id']?>"><input type="hidden" name="status" value="draft"><button class="btn btn-sm btn-light">بازکردن</button></form><?php else:?><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$exam['id']?>"><input type="hidden" name="status" value="published"><button class="btn btn-sm btn-success">انتشار</button></form><?php endif;?></div></td></tr><?php endforeach;endif;?></tbody></table></div><?php require __DIR__.'/../partials/footer.php'; ?>
